import type { Metadata } from "next";
import { GameLandingPage } from "@/components/marketing/GameLandingPage";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const metadata: Metadata = {
  title: "Palworld VPS Server Hosting — Up to 32 Players, Instant Setup",
  description:
    "Palworld server hosting from $14.99/mo. Full 32-player dedicated servers, auto-restarts for the memory leak, full file access and instant setup on a low-latency network.",
  alternates: { canonical: "/palworld-server-hosting" },
  openGraph: {
    type: "article",
    title: "Palworld VPS Server Hosting — Up to 32 Players, Instant Setup",
    description:
      "Managed Palworld hosting: 32-player servers, scheduled auto-restarts, full file access and instant setup. From $14.99/mo.",
    url: `${APP_URL}/palworld-server-hosting`,
  },
};

const FAQ = [
  {
    q: "How much RAM do I need for a Palworld server?",
    a: "Plan for 16 GB as your practical baseline. Palworld is heavy: a fresh co-op world idles fine on 8 GB, but a busy 32-player server with lots of built bases climbs toward 24–32 GB over time. Our 16 GB / 32-player plan is the recommended pick for a full server, and you can scale up whenever your world grows.",
  },
  {
    q: "How many players can a Palworld server hold?",
    a: "Palworld's dedicated server caps at 32 players. Our 16 GB plan is sized for a full 32-slot server; the 8 GB plan suits a smaller co-op group.",
  },
  {
    q: "What port does Palworld use?",
    a: "Palworld uses UDP port 8211 by default. On a managed Nxeon server the port is opened and the connect string is handed to you automatically — nothing to forward.",
  },
  {
    q: "My Palworld server's RAM keeps climbing — is that normal?",
    a: "Yes. Palworld has a well-known memory leak where RAM usage grows the longer the server runs, especially with large bases. The standard fix is a scheduled restart every 6–12 hours to reclaim memory, which you can automate from the panel so players never notice.",
  },
  {
    q: "Can I add mods and change server settings?",
    a: "Yes. You get full file access to edit PalWorldSettings.ini — day/night length, capture rates, difficulty, XP multipliers — and to drop in mods. Changes apply on the next restart.",
  },
  {
    q: "Is Palworld hosting a VPS?",
    a: "Yes — every Palworld server here runs on a dedicated VPS with its own guaranteed CPU, RAM and NVMe storage, plus full file and SFTP access. You get the raw power and control of a VPS, but we handle the SteamCMD install, port setup, patch-day updates and auto-restarts for you, so you skip the manual server administration.",
  },
];

export default function PalworldServerHostingPage() {
  return (
    <GameLandingPage
      family="palworld"
      hero={{
        title: "Palworld VPS server",
        highlight: "hosting",
        sub: "Managed Palworld hosting on a dedicated VPS for a full 32-player world — scheduled auto-restarts to beat the memory leak, full file access, and instant setup on a low-latency network. From $14.99/mo.",
        primary: { label: "See Palworld plans", href: "/game-servers" },
        secondary: { label: "Create your account", href: "/register" },
      }}
      intro={[
        "Palworld is one of the most demanding survival games to host. A 32-player world with sprawling bases chews through RAM, and the engine's well-documented memory leak means usage keeps climbing the longer the server runs. Doing it on a raw box means SteamCMD, patch-day updates, tuning PalWorldSettings.ini, and manually restarting before the server chokes.",
        "Our managed Palworld hosting handles that. Servers are provisioned in minutes on port 8211, scheduled auto-restarts reclaim leaked memory every few hours so nobody gets a mid-raid crash, and full file access lets you edit every setting or drop in mods when you want control beyond the panel.",
        "Palworld's dedicated server caps at 32 players, so size for the world you want: an 8 GB plan for a small co-op group, or the recommended 16 GB plan for a packed 32-slot server with base-building headroom. Scale up whenever your Pals — and your player list — outgrow it.",
      ]}
      plansTitle="Pick your Palworld plan"
      plansSub="Priced by RAM and players. Every plan includes scheduled auto-restarts, full file access, and instant setup."
      plansCta={{ label: "Get started", href: "/game-servers" }}
      plans={[
        {
          name: "8 GB",
          price: "$14.99",
          meta: "8 players",
          blurb: "A co-op Palworld world for a small group of Pal tamers to build and explore.",
        },
        {
          name: "16 GB",
          price: "$27.99",
          meta: "32 players",
          blurb: "The recommended pick — a full 32-player server with headroom for big bases.",
          popular: true,
        },
      ]}
      whyTitle="Built for Palworld"
      why={[
        { title: "Sized for 32 players", body: "Palworld caps at 32 slots and is RAM-hungry — our 16 GB plan is built to run a full server without the late-session slowdown." },
        { title: "Auto-restart the leak away", body: "Palworld's memory usage climbs over time. Scheduled restarts every few hours reclaim it automatically, so players never hit a crash mid-raid." },
        { title: "Full file access", body: "Edit PalWorldSettings.ini — capture rates, difficulty, day length, XP — and drop in mods directly, then apply on the next restart." },
        { title: "Instant setup", body: "Your Palworld server is provisioned and online within minutes on port 8211, with its connect string ready to share." },
        { title: "Low-latency network", body: "Hosted from our Singapore datacenter for tight ping across Asia-Pacific — smoother combat and base raids." },
        { title: "Scale anytime", body: "Start on 8 GB and move up to 16 GB when your co-op group turns into a packed 32-player world. Your save comes with you." },
      ]}
      stepsTitle="Playing in minutes"
      steps={[
        { title: "Pick a Palworld plan", body: "Choose 8 GB for a small co-op group or 16 GB for a full 32-player server." },
        { title: "Server goes live in minutes", body: "Your Palworld server is provisioned on port 8211 and online almost immediately." },
        { title: "Tune your world", body: "Edit PalWorldSettings.ini from the panel or over file access, and set your auto-restart schedule." },
        { title: "Invite your friends", body: "Share the connect string and start catching Pals together." },
      ]}
      guides={[
        { label: "How to set up a Palworld dedicated server on a VPS", href: "/blog/how-to-set-up-a-palworld-dedicated-server-on-a-vps" },
        { label: "Palworld dedicated server requirements: RAM and CPU", href: "/blog/palworld-dedicated-server-requirements-ram-and-cpu" },
        { label: "How to configure a Palworld server: settings explained", href: "/blog/how-to-configure-a-palworld-server-settings-explained" },
        { label: "Best VPS specs for a Palworld server", href: "/blog/best-vps-specs-for-a-palworld-server" },
      ]}
      faq={FAQ}
      related={[
        { label: "All game servers", href: "/game-servers" },
        { label: "Valheim server hosting", href: "/valheim-server-hosting" },
        { label: "ARK server hosting", href: "/ark-server-hosting" },
        { label: "Gaming VPS", href: "/gaming-vps" },
        { label: "Pricing", href: "/pricing" },
      ]}
    />
  );
}
