54	function TpsGraph({ accent, active, reduced }: { accent: string; active: boolean; reduced: boolean }) {
55	  const pts = [19.9, 20, 19.8, 20, 20, 19.7, 20, 19.9, 20, 20, 19.8, 20];
56	  const w = 220;
57	  const h = 46;
58	  const min = 19.5;
59	  const max = 20.2;
60	  const step = w / (pts.length - 1);
61	  const coords = pts.map((v, i) => {
62	    const x = i * step;
63	    const y = h - ((v - min) / (max - min)) * h;
64	    return [x, y] as const;
65	  });
66	  const line = coords.map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(1)} ${y.toFixed(1)}`).join(" ");
67	  const area = `${line} L${w} ${h} L0 ${h} Z`;
68	  const [ex, ey] = coords[coords.length - 1];
69	  return (
70	    <svg viewBox={`0 0 ${w} ${h}`} className="h-[46px] w-full" preserveAspectRatio="none" aria-hidden>
71	      <defs>
72	        <linearGradient id="pv-cmb-tps-fill" x1="0" y1="0" x2="0" y2="1">
73	          <stop offset="0%" stopColor={accent} stopOpacity="0.35" />
74	          <stop offset="100%" stopColor={accent} stopOpacity="0" />
75	        </linearGradient>
76	      </defs>
77	      <path d={area} fill="url(#pv-cmb-tps-fill)" />
78	      <path
79	        d={line}
80	        fill="none"
81	        stroke={accent}
82	        strokeWidth="1.6"
83	        strokeLinecap="round"
84	        strokeLinejoin="round"
85	        className={reduced || !active ? "" : "pv-draw"}
86	      />
87	      <circle cx={ex} cy={ey} r="3" fill={accent} className={reduced ? "" : "motion-safe:animate-pulse-dot"} />
88	    </svg>
89	  );
90	}
